#!/usr/bin/env python3
from __future__ import annotations
import argparse,json
from pathlib import Path
def main():
 p=argparse.ArgumentParser();p.add_argument('--evidence',type=Path,required=True);p.add_argument('--rule',type=Path,required=True);p.add_argument('--protocol-lock',type=Path,required=True);p.add_argument('--selection-lock',type=Path,required=True);p.add_argument('--evaluation-lock',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--report',type=Path,required=True);a=p.parse_args();e=json.loads(a.evidence.read_text());r=json.loads(a.rule.read_text());pl=json.loads(a.protocol_lock.read_text());sl=json.loads(a.selection_lock.read_text());el=json.loads(a.evaluation_lock.read_text());go=r['go_stage7'];checks={'new_seed_improved_count_ge_2':e['new_seed_improved_count']>=go['new_seed_improved_count_min'],'combined_graph_gain_ge_0_05':e['combined_graph_task_success_gain']>=go['combined_graph_task_success_gain_min'],'combined_fixed_order_drop_le_0_05':e['combined_fixed_order_drop']<=go['combined_fixed_order_drop_max'],'structure_specific_gain':e['combined_recovery_success_gain']>=go['structure_specific_any']['combined_recovery_success_gain_min'] or e['combined_worst_order_success_gain']>=go['structure_specific_any']['combined_worst_order_success_gain_min'] or e['combined_long_horizon_completion_gain']>=go['structure_specific_any']['combined_long_horizon_completion_gain_min'],'paired_evaluation':e['paired_evaluation'] is True,'reward_retuned_after_test':e['reward_retuned_after_test'] is False,'protocol_input_locked':pl.get('locked') is True,'selection_locked':sl.get('locked') is True,'evaluation_locked':el.get('locked') is True,'combined_seed_count_6':e['combined_seed_count']==6}
 decision='GO_STAGE7' if all(checks.values()) else 'NARROW_TO_REWARD_ONLY';result={'decision':decision,'checks':checks,'rule_sha256':__import__('hashlib').sha256(a.rule.read_bytes()).hexdigest(),'evidence':e};a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(result,indent=2)+'\n');a.report.write_text('# G3-R1 decision\n\nDecision: `'+decision+'`\n\n'+json.dumps(checks,indent=2)+'\n');print(json.dumps(result,indent=2))
if __name__=='__main__':main()
